#!/usr/bin/env node
/**
 * build-variants.js — generate the two MTD quiz placement prototypes.
 *
 * Figma file NcVP4hGOouCZHJkIYJR4tb, page 3370:69660 "Quizz":
 *   3767:2716  Variant A — before click (1920x14408)
 *   3776:6405  Variant A — modal open  (1920x1080)
 *   3795:3228  Variant B — HMRC intro + inline quiz (1920x15107)
 *
 * Variant A: the registered page minus the quiz banner and the inline quiz, plus
 * a secondary hero CTA ("Take the MTD check") that opens the quiz modal. The
 * primary "Get free MTD software" keeps its own destination.
 *
 * Variant B: the gradient HMRC intro replaces the quiz banner at the top, the
 * inline quiz takes the HMRC-letter slot after pricing (that block moves to the
 * top), and the hero keeps its single primary CTA with no modal binding.
 *
 * ONE SOURCE, TWO OUTPUTS. The source is mtd-income-tax/index.html. Do not edit
 * variant-a/index.html or variant-b/index.html by hand — edit this file (or the
 * registered page) and re-run. Every patch asserts its anchor exactly once and
 * the build fails loudly if the source moved.
 *
 * Each output also gets its own <title> first segment ("Variant A — quiz modal" /
 * "Variant B — inline quiz") because the hub card labels links from it.
 *
 *   node ongoing_project/MTD/build-variants.js
 *   node ongoing_project/MTD/build-variants.js --check   (exit 1 if stale)
 */
'use strict';
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const HERE = __dirname;
const SRC = path.join(HERE, 'mtd-income-tax', 'index.html');
const OUT = {
  a: path.join(HERE, 'variant-a', 'index.html'),
  b: path.join(HERE, 'variant-b', 'index.html'),
};

// Section boundaries, taken from the markers the page already carries. A slice runs
// from its own comment to (but not including) the next section's comment.
const MARKERS = {
  banner: ['<!-- the quiz banner (Roadmap 4.4) -->', '<!-- §1 MTD hero (components/mtd-hero) -->'],
  quiz: ['<!-- the quiz (Roadmap 4.3) -->', '<!-- §2 PS01 pricing (components/mtd-pricing) -->'],
  hmrc: ['<!-- §3 HMRC letter (components/mtd-hmrc-letter) -->', '<!-- §4 CB07 what is MTD (components/mtd-what-is) -->'],
};

const MODAL_SCRIPT = '<script src="quiz-modal.js"></script>';

// The hub labels each card link with the page title's first "|" segment
// (tooling/hub-build.js pageTitle), so the two variants must not inherit the
// registered page's title verbatim or the hub shows two identical links.
const SRC_TITLE = '<title>Free Making Tax Digital Software | MTD for Income Tax | Sage UK</title>';
const titleFor = (label) => `<title>${label} | MTD for Income Tax | Sage UK</title>`;
const HERO_GROUP = '<div class="score-button-group ">';
const HERO_GROUP_A = '<div class="score-button-group mtd-hero-ctas">';

// The source modal (mtd-income-tax/index.html). Variant A replaces the whole
// block: head/foot chrome are dropped for Figma 3776:6405 — the dialog is just
// a black panel, the 1440 quiz, and a 24px X in the top-right corner. The
// visible title lives inside the quiz iframe; a visually-hidden h2 in the
// parent keeps aria-labelledby resolvable. The X is a real <button>, not a
// score-button class, so the one-look-per-button-class rule is unaffected.
const MODAL_SRC = `<div class="mtd-quiz-modal" id="mtd-quiz-modal" role="dialog" aria-modal="true" aria-labelledby="mtd-quiz-modal-title" hidden>
  <div class="mtd-quiz-modal-backdrop" data-mtd-modal-close></div>
  <div class="mtd-quiz-modal-panel theme-dark" role="document">
    <div class="mtd-quiz-modal-head">
      <h2 id="mtd-quiz-modal-title">Making Tax Digital quiz</h2>
      <button type="button" class="score-button button--secondary mtd-quiz-modal-close" data-mtd-modal-close aria-label="Close the quiz">Close</button>
    </div>
    <iframe id="mtd-quiz-modal-frame" class="mtd-quiz-frame" src="quiz/index.html" title="Making Tax Digital quiz: seven questions about your HMRC letter"></iframe>
    <div class="mtd-quiz-modal-foot">
      <button type="button" class="score-button button--secondary mtd-quiz-modal-close" data-mtd-modal-close>Close the quiz</button>
    </div>
  </div>
</div>`;

const MODAL_FIGMA_A = `<div class="mtd-quiz-modal mtd-quiz-modal--figma-a" id="mtd-quiz-modal" role="dialog" aria-modal="true" aria-labelledby="mtd-quiz-modal-title" hidden>
  <div class="mtd-quiz-modal-backdrop" data-mtd-modal-close></div>
  <div class="mtd-quiz-modal-panel theme-dark" role="document">
    <h2 id="mtd-quiz-modal-title" class="mtd-quiz-modal-title-vh">Get your tailored MTD guidance</h2>
    <iframe id="mtd-quiz-modal-frame" class="mtd-quiz-frame" src="quiz/index.html" title="Making Tax Digital quiz: seven questions about your HMRC letter"></iframe>
    <button type="button" class="mtd-quiz-modal-close" data-mtd-modal-close aria-label="Close the quiz">
      <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false"><path d="M12 2C6.48603 2 2 6.48604 2 12C2 17.514 6.48603 22 12 22C17.514 22 22 17.514 22 12C22 6.48604 17.514 2 12 2ZM12 3.5C16.7033 3.5 20.5 7.2967 20.5 12C20.5 16.7033 16.7033 20.5 12 20.5C7.29669 20.5 3.5 16.7033 3.5 12C3.5 7.2967 7.29669 3.5 12 3.5ZM15.2432 7.98926C15.0451 7.99394 14.8569 8.07679 14.7197 8.21973L12 10.9395L9.28027 8.21973C9.21036 8.14773 9.12672 8.0905 9.03429 8.05142C8.94187 8.01233 8.84254 7.99219 8.74219 7.99219C8.59293 7.99222 8.44707 8.03679 8.32328 8.12019C8.19949 8.20358 8.1034 8.32202 8.0473 8.46033C7.99119 8.59865 7.97763 8.75056 8.00835 8.89662C8.03907 9.04269 8.11267 9.17627 8.21973 9.28027L10.9395 12L8.21973 14.7197C8.14775 14.7888 8.09028 14.8716 8.0507 14.9632C8.01111 15.0548 7.9902 15.1534 7.98918 15.2532C7.98817 15.3529 8.00707 15.4519 8.04479 15.5443C8.08251 15.6367 8.13828 15.7206 8.20883 15.7912C8.27939 15.8617 8.36332 15.9175 8.4557 15.9552C8.54808 15.9929 8.64706 16.0118 8.74684 16.0108C8.84662 16.0098 8.9452 15.9889 9.03679 15.9493C9.12839 15.9097 9.21116 15.8523 9.28027 15.7803L12 13.0605L14.7197 15.7803C14.7888 15.8523 14.8716 15.9097 14.9632 15.9493C15.0548 15.9889 15.1534 16.0098 15.2532 16.0108C15.3529 16.0118 15.4519 15.9929 15.5443 15.9552C15.6367 15.9175 15.7206 15.8617 15.7912 15.7912C15.8617 15.7206 15.9175 15.6367 15.9552 15.5443C15.9929 15.4519 16.0118 15.3529 16.0108 15.2532C16.0098 15.1534 15.9889 15.0548 15.9493 14.9632C15.9097 14.8716 15.8523 14.7888 15.7803 14.7197L13.0605 12L15.7803 9.28027C15.8893 9.17559 15.9642 9.0404 15.9951 8.89242C16.026 8.74444 16.0115 8.59058 15.9534 8.451C15.8953 8.31143 15.7965 8.19266 15.6697 8.11026C15.543 8.02787 15.3943 7.98569 15.2432 7.98926Z" fill="white"/></svg>
    </button>
  </div>
</div>`;

function fail(message) {
  console.error('FAIL ' + message);
  process.exit(1);
}

function count(haystack, needle) {
  return haystack.split(needle).length - 1;
}

function cut(html, [start, end], label) {
  const s = html.indexOf(start);
  const e = html.indexOf(end);
  if (s < 0) fail(`${label}: start marker missing (${start})`);
  if (e < 0) fail(`${label}: end marker missing (${end})`);
  if (e <= s) fail(`${label}: end marker appears before start`);
  return html.slice(s, e);
}

function replaceOnce(html, needle, replacement, label) {
  const n = count(html, needle);
  if (n !== 1) fail(`${label}: expected 1 occurrence, found ${n}`);
  return html.replace(needle, replacement);
}

/** The generated pages live one folder across from the registered one, so every
 *  same-folder reference has to be pointed at it. Component paths
 *  (../../../components/…) resolve identically at this depth and are untouched. */
function prefixPaths(html, label) {
  // Generic on purpose: any local reference that is not already relative-to-parent,
  // root-absolute, a fragment, or a data/mailto/http URL lives beside the registered
  // page and must be pointed at it. A fixed allow-list silently missed a new file
  // (variant-quiz.js) and shipped a 404.
  let out = html.replace(
    /(\s(?:src|href|data-path)=")(?!\.\.\/|#|\/|https?:|data:|mailto:)([^"]+)"/g,
    '$1../mtd-income-tax/$2"'
  );
  out = out.replace(/url\('assets\//g, "url('../mtd-income-tax/assets/");
  out = out.replace(/url\("assets\//g, 'url("../mtd-income-tax/assets/');
  if (/(\s(?:src|href|data-path)=")(?!\.\.\/|#|\/|https?:|data:|mailto:)/.test(out)) {
    fail(`${label}: a same-folder reference was left unprefixed`);
  }
  if (!out.includes('src="../mtd-income-tax/variant-quiz.js"')) {
    fail(`${label}: the variant quiz script was not wired`);
  }
  return out;
}

/** Variant B's intro — Figma 3810:4255. Copy is verbatim from the frame. */
function introSection() {
  return `<!-- §0b HMRC intro (Figma 4.11 Variant B, node 3810:4255) -->
<section class="mtd-quiz-intro theme-dark" aria-label="Got a letter from HMRC? Don't panic">
  <div class="container fixed-grid">
    <div class="mtd-quiz-intro-card">
      <div class="mtd-quiz-intro-media" aria-hidden="true"></div>
      <div class="mtd-quiz-intro-content">
        <p class="mtd-quiz-intro-eyebrow">Check. Connect. Catch-up.</p>
        <h2 class="mtd-quiz-intro-title">Got a letter from HMRC? <span class="mtd-quiz-intro-accent">Don't panic</span></h2>
        <p class="mtd-quiz-intro-body">If HMRC has signed you up for MTD, Sage makes it simple to get started. Check your details, connect your account and catch up with your first update to HMRC.</p>
        <a class="score-button button-checkout mtd-quiz-intro-cta" href="#mtd-quiz">Start the MTD check</a>
      </div>
    </div>
  </div>
</section>

`;
}

/** Variant A's secondary hero CTA — Figma 3792:4262. */
function addHeroSecondary(html) {
  const heroStart = html.indexOf('<!-- §1 MTD hero (components/mtd-hero) -->');
  const heroEnd = html.indexOf('<!-- §2 PS01 pricing (components/mtd-pricing) -->');
  if (heroStart < 0 || heroEnd <= heroStart) fail('variant A: hero slice not found');
  let hero = html.slice(heroStart, heroEnd);

  if (count(hero, HERO_GROUP) !== 1) fail('variant A: hero button group not unique');
  hero = replaceOnce(hero, HERO_GROUP, HERO_GROUP_A, 'variant A: hero group class');

  const groupAt = hero.indexOf(HERO_GROUP_A) + HERO_GROUP_A.length;
  const anchorEnd = hero.indexOf('</a>', groupAt);
  if (anchorEnd < 0) fail('variant A: hero primary anchor not found');
  if (!/Get free MTD software/.test(hero.slice(groupAt, anchorEnd))) {
    fail('variant A: hero CTA is not the expected primary button');
  }

  const secondary =
    '\n    <a class="score-button button--secondary" href="#mtd-quiz-modal" data-mtd-quiz-trigger' +
    ' aria-haspopup="dialog" aria-controls="mtd-quiz-modal">Take the MTD check</a>';
  const at = anchorEnd + 4;
  hero = hero.slice(0, at) + secondary + hero.slice(at);

  return html.slice(0, heroStart) + hero + html.slice(heroEnd);
}

function banner(title, note) {
  return `<!doctype html>
<!-- GENERATED FILE — do not edit.
     Built by ongoing_project/MTD/build-variants.js from mtd-income-tax/index.html.
     ${note}
     Figma: NcVP4hGOouCZHJkIYJR4tb / page 3370:69660 "Quizz" / ${title} -->
`;
}

function build() {
  const source = fs.readFileSync(SRC, 'utf8');
  if (count(source, '<!-- sage-page-gate -->') !== 1) fail('source: page gate missing');

  const bannerBlock = cut(source, MARKERS.banner, 'banner');
  const quizBlock = cut(source, MARKERS.quiz, 'inline quiz');
  const hmrcBlock = cut(source, MARKERS.hmrc, 'hmrc letter');

  // Both variants land on Step 1 of 7, as Figma draws it, so both load the
  // entry-screen skipper. The registered page never does.
  const withVariantQuiz = (html, label) =>
    replaceOnce(
      html,
      '<script src="quiz-frame.js"></script>',
      '<script src="quiz-frame.js"></script>\n<script src="variant-quiz.js"></script>',
      label + ': variant quiz script'
    );

  // ---- Variant A -----------------------------------------------------------
  let a = replaceOnce(source, bannerBlock, '', 'variant A: drop banner');
  a = replaceOnce(a, quizBlock, '', 'variant A: drop inline quiz');
  a = addHeroSecondary(a);
  a = replaceOnce(a, MODAL_SRC, MODAL_FIGMA_A, 'variant A: Figma 3776:6405 dialog (no head/foot, X close)');
  a = withVariantQuiz(a, 'variant A');
  a = replaceOnce(a, SRC_TITLE, titleFor('Variant A \u2014 quiz modal'), 'variant A: distinct title');
  a = prefixPaths(a, 'variant A');
  a = banner('3767:2716 Variant A — before click', 'Variant A: hero secondary CTA opens the modal.') + a;

  // ---- Variant B -----------------------------------------------------------
  let b = replaceOnce(source, bannerBlock, introSection(), 'variant B: intro replaces banner');
  b = replaceOnce(b, quizBlock, '', 'variant B: drop quiz from after the hero');
  b = replaceOnce(b, hmrcBlock, quizBlock, 'variant B: quiz takes the HMRC-letter slot');
  b = replaceOnce(b, MODAL_SCRIPT, '', 'variant B: no modal binding (hero CTA is a plain link)');
  b = withVariantQuiz(b, 'variant B');
  b = replaceOnce(b, SRC_TITLE, titleFor('Variant B \u2014 inline quiz'), 'variant B: distinct title');
  b = prefixPaths(b, 'variant B');
  b = banner('3795:3228 Variant B — HMRC intro + inline quiz', 'Variant B: gradient intro on top, quiz after pricing.') + b;

  return { a, b };
}

function md5(s) {
  return crypto.createHash('md5').update(s).digest('hex').slice(0, 8);
}

function main() {
  const check = process.argv.includes('--check');
  const { a, b } = build();

  for (const [key, html] of [['a', a], ['b', b]]) {
    const file = OUT[key];
    const rel = path.relative(path.join(HERE, '..', '..'), file);
    if (check) {
      const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
      if (current !== html) {
        console.error(`STALE ${rel} — re-run node ongoing_project/MTD/build-variants.js`);
        process.exitCode = 1;
      } else {
        console.log(`ok    ${rel} (${html.length} bytes, md5 ${md5(html)})`);
      }
      continue;
    }
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, html);
    console.log(`wrote ${rel} (${html.length} bytes, md5 ${md5(html)})`);
  }

  if (check && process.exitCode) return;
  if (!check) {
    // The two pages are different by construction; this is the guard against a patch
    // silently becoming a no-op and shipping two copies of the same page.
    const aOnly = a.replace(/Variant A[^\n]*/g, '');
    const bOnly = b.replace(/Variant B[^\n]*/g, '');
    if (aOnly === bOnly) fail('variants came out identical — a patch was a no-op');
    console.log('ok    variants differ');
  }
}

main();

