display.text:
/* MTD quiz placement. All spacing is on the 4px grid; colours come from the
   page's Sage token set (see main.css :root / .theme-dark). */

.mtd-quiz-banner {
  background: var(--theme-background-color);
  color: var(--text-primary-inverse);
}

.mtd-quiz-banner .container {
  padding-top: 16px;
  padding-bottom: 16px;
}

.mtd-quiz-banner-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 16px 24px;
  border: 1px solid rgba(255, 255, 255, 0.3);
  border-radius: 16px;
  background: var(--theme-background-color);
}

.mtd-quiz-banner-copy {
  min-width: 0;
}

.mtd-quiz-banner-title {
  margin: 0 0 4px;
  color: var(--text-primary);
  font-family: inherit;
  font-size: 20px;
  font-weight: 700;
  line-height: 1.3;
}

.mtd-quiz-banner-sub {
  margin: 0;
  color: var(--text-secondary);
  font-family: inherit;
  font-size: 16px;
  line-height: 1.4;
}

.mtd-quiz-banner-cta.score-button {
  flex: 0 0 auto;
  min-height: 48px;
  padding: 12px 24px;
  border-radius: 999px;
  font-family: inherit;
  font-weight: 700;
  text-decoration: none;
  white-space: nowrap;
}

.mtd-quiz-section {
  background: var(--theme-background-color);
  padding: 32px 0 48px;
  scroll-margin-top: 80px;
}

.mtd-quiz-frame {
  display: block;
  width: 100%;
  min-height: 640px;
  border: 0;
  border-radius: 16px;
  background: var(--theme-background-color);
}

/* Variant A: the quiz in a dialog opened from the hero CTA. */
.mtd-quiz-modal[hidden] {
  display: none;
}

.mtd-quiz-modal {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.mtd-quiz-modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.8);
}

.mtd-quiz-modal-panel {
  position: relative;
  display: flex;
  flex-direction: column;
  width: min(1200px, 100%);
  max-height: calc(100vh - 48px);
  overflow: hidden;
  border-radius: 16px;
  background: var(--theme-background-color);
}

.mtd-quiz-modal-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 24px;
}

.mtd-quiz-modal-head h2 {
  margin: 0;
  color: var(--text-primary);
  font-family: inherit;
  font-size: 24px;
  line-height: 1.3;
}

.mtd-quiz-modal-close {
  flex: 0 0 auto;
  min-height: 48px;
  padding: 12px 24px;
}

.mtd-quiz-modal-foot {
  display: flex;
  justify-content: flex-end;
  padding: 16px 24px;
}

.mtd-quiz-modal-panel .mtd-quiz-frame {
  flex: 1 1 auto;
  height: calc(100vh - 192px);
  min-height: 0;
  border-radius: 0;
}

@media (max-width: 767px) {
  .mtd-quiz-banner-card {
    display: block;
    padding: 16px;
  }

  .mtd-quiz-banner-cta.score-button {
    display: inline-block;
    margin-top: 16px;
  }

  .mtd-quiz-section {
    padding: 24px 0 32px;
  }

  .mtd-quiz-frame {
    border-radius: 0;
  }

  .mtd-quiz-modal {
    padding: 16px;
  }

  .mtd-quiz-modal-panel {
    max-height: calc(100vh - 32px);
  }
}

/* The export keeps its <h1> in a breakpoint-hidden wrapper because the hero
   headline is Lottie artwork. Keep exactly one real h1 for assistive tech,
   visually hidden but present in the accessibility tree. */
.score-content-spot.hidden-xs.hidden-sm.hidden-md.hidden-lg:has(> h1) {
  display: block !important;
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
  clip: rect(0 0 0 0) !important;
  clip-path: inset(50%) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

/* A5: guarantee a visible keyboard focus ring on every page-level control,
   including controls whose component CSS removes the UA outline. */
body a:focus-visible,
body button:focus-visible,
body input:focus-visible,
body select:focus-visible,
body textarea:focus-visible,
body summary:focus-visible,
body [tabindex]:focus-visible,
body iframe:focus {
  outline: 3px solid var(--sage-brilliant-green) !important;
  outline-offset: 2px !important;
}

/* ── Roadmap 4.17: Variant A / B prototypes (Figma 4.11) ──────────────────
   Styles for the two generated pages in ongoing_project/MTD/variant-a/ and
   variant-b/ (built by ongoing_project/MTD/build-variants.js from this page).
     A  secondary hero CTA "Take the MTD check" that opens the quiz modal;
     B  the gradient HMRC intro at the top and the quiz in the HMRC-letter slot.
   Every rule below is scoped to classes only those generated pages carry, so
   the registered mtd-income-tax page renders exactly as before. */

.mtd-hero-ctas {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 16px;
}



.mtd-quiz-intro {
  padding-top: 40px;
}

.mtd-quiz-intro-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 855px);
  gap: 48px;
  align-items: center;
  padding: 48px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 24px;
  background:
    radial-gradient(120% 130% at 8% 100%, rgba(107, 79, 216, 0.55) 0%, rgba(107, 79, 216, 0) 55%),
    radial-gradient(120% 130% at 96% 60%, rgba(31, 158, 143, 0.55) 0%, rgba(31, 158, 143, 0) 60%),
    linear-gradient(100deg, #0b0b0f 0%, #141420 45%, #0b0b0f 100%);
}

.mtd-quiz-intro-eyebrow {
  display: inline-block;
  margin: 0 0 24px;
  padding: 8px 16px;
  border: 1px solid rgba(255, 255, 255, 0.4);
  border-radius: 999px;
  color: #fff;
  font-size: 16px;
  line-height: 24px;
}

.mtd-quiz-intro-title {
  margin: 0 0 24px;
  color: #fff;
  font-size: clamp(28px, 3vw, 40px);
  line-height: 1.2;
}

.mtd-quiz-intro-accent {
  color: var(--sage-brilliant-green);
}

.mtd-quiz-intro-body {
  max-width: 855px;
  margin: 0 0 32px;
  color: rgba(255, 255, 255, 0.9);
  font-size: 16px;
  line-height: 24px;
}

@media (max-width: 767px) {
  .mtd-quiz-intro {
    padding-top: 24px;
  }

  .mtd-quiz-intro-card {
    grid-template-columns: minmax(0, 1fr);
    gap: 24px;
    padding: 24px;
  }

  .mtd-hero-ctas {
    gap: 8px;
  }
}

/* Variant A's dialog matches Figma 3776:6405 (panel 1520 × ~597 at 200,242 on
   a 1920 canvas): black fill, 1px #474747 border, 40px radius, 40px padding,
   backdrop near-black, and a 24px X in the top-right corner. The only close
   control is that real <button> — no head/foot chrome. Scoped to the generated
   page so the registered page keeps its approved 1200 shell. */
.mtd-quiz-modal--figma-a .mtd-quiz-modal-backdrop {
  background: #000;
}

.mtd-quiz-modal--figma-a .mtd-quiz-modal-panel {
  width: min(1520px, 100%);
  max-height: calc(100vh - 48px);
  /* The dialog hugs its content: the iframe is fitted to the quiz's rendered
     height by variant-quiz.js, and this box never scrolls — when a viewport is
     too short the iframe itself scrolls (thin scrollbar, see the frame rule),
     so no scrollbar can ever run under the X. */
  overflow: hidden;
  border: 1px solid #474747;
  border-radius: 40px;
  background: #000;
  padding: 40px;
  /* room for the absolutely-positioned close button so it never overlaps the
     quiz title's first line */
  box-sizing: border-box;
}

/* Visually hidden title: the visible one lives inside the quiz iframe; this
   keeps aria-labelledby resolvable in the parent document. */
.mtd-quiz-modal--figma-a .mtd-quiz-modal-title-vh {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
  clip: rect(0 0 0 0) !important;
  clip-path: inset(50%) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

/* Height is fitted to the quiz content by variant-quiz.js (the quiz's React
   tree mounts asynchronously, so a static height is always wrong). The
   max-height keeps the frame inside the panel when the viewport is short:
   100vh − 48 (modal padding) − 80 (panel padding) − 2 (panel border). Past
   that the frame's own document scrolls with the thin scrollbar defined in
   variant-quiz-figma.css — 40px in from the panel edge, clear of the X. */
.mtd-quiz-modal--figma-a .mtd-quiz-modal-panel .mtd-quiz-frame {
  height: auto;
  min-height: 0;
  max-height: calc(100vh - 130px);
  border-radius: 0;
  background: #000;
}

/* The only close control: a bare 24 × 24 button pinned to the dialog's
   top-right, on the 48px padding grid (40 padding + 8). Not a score-button —
   the one-look-per-button-class rule does not apply to it. */
.mtd-quiz-modal--figma-a .mtd-quiz-modal-close {
  position: absolute;
  top: 48px;
  right: 48px;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  /* the page-wide button rule sets min-width: 96px; the X is 24px */
  min-width: 0;
  min-height: 0;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: transparent;
  font-size: 0;
  line-height: 0;
  cursor: pointer;
}

.mtd-quiz-modal--figma-a .mtd-quiz-modal-close svg {
  display: block;
  width: 24px;
  height: 24px;
}

.mtd-quiz-modal--figma-a .mtd-quiz-modal-close:hover svg,
.mtd-quiz-modal--figma-a .mtd-quiz-modal-close:focus-visible svg,
.mtd-quiz-modal--figma-a .mtd-quiz-modal-close:active svg {
  opacity: 0.85;
