/* The vendor bundle styles every bare <button> (main.css `button:not(…)`):
   a ::after ripple that scales ×400 on :hover/:focus/:active and a filled
   :focus/:active background. The dialog focuses the X on open, so that
   ripple painted a green square behind the icon at every viewport. Kill the
   pseudo-element and keep the button's own box transparent in every state —
   keyboard focus keeps the page's standard plain outline ring (the
   body button:focus-visible rule in this file). */
.mtd-quiz-modal--figma-a .mtd-quiz-modal-close::before,
.mtd-quiz-modal--figma-a .mtd-quiz-modal-close::after {
  content: none;
  display: none;
}

.mtd-quiz-modal--figma-a .mtd-quiz-modal-close:focus,
.mtd-quiz-modal--figma-a .mtd-quiz-modal-close:active {
  background: transparent;
  color: transparent;
  border: 0;
  outline: none;
}

.mtd-quiz-modal--figma-a .mtd-quiz-modal-close:focus-visible {
  outline: 3px solid var(--sage-brilliant-green);
  outline-offset: 2px;
}

/* Laptop widths: the dialog's outer air drops to the next 4px step so the
   quiz keeps its width at ~1024. Frame budget: 100vh − 32 (modal padding)
   − 48 (panel padding) − 2 (panel border). 1280 / 1440 / 1920 keep the
   Figma-exact 24/40 values above. */
@media (max-width: 1199px) {
  .mtd-quiz-modal--figma-a {
    padding: 16px;
  }

  .mtd-quiz-modal--figma-a .mtd-quiz-modal-panel {
    max-height: calc(100vh - 32px);
    padding: 24px;
  }

  .mtd-quiz-modal--figma-a .mtd-quiz-modal-panel .mtd-quiz-frame {
    max-height: calc(100vh - 82px);
  }

  .mtd-quiz-modal--figma-a .mtd-quiz-modal-close {
    top: 32px;
    right: 32px;
  }
}

/* Layout only (no button state): pricing-card CTAs fill the card width. States come from the shared button class. */
.sage-product-card-outer .sage-product-card-cta-wrapper-alt .score-button {
  width: 100%;
}

