/* Keep the embedded quiz flush with its own content so the iframe never grows
   an inner scrollbar. Same-origin static hosting: read the document height and
   follow the quiz's own screen-change event. Under file:// the read is blocked
   by the browser's opaque origin; the CSS min-height then keeps the frame
   usable. */
(function () {
  var frame = document.getElementById("mtd-quiz-frame");
  if (!frame) return;
  var timer = 0;

  function fit() {
    try {
      var doc = frame.contentDocument;
      if (!doc || !doc.documentElement) return;
      var height = Math.max(
        doc.documentElement.scrollHeight,
        doc.body ? doc.body.scrollHeight : 0,
        640
      );
      if (height > 0) {
        var next = Math.ceil(height);
        if (Math.abs(frame.getBoundingClientRect().height - next) > 1) {
          frame.style.height = next + "px";
        }
      }
    } catch (error) {
      /* file:// opaque origin: leave the CSS min-height in place */
    }
  }

  function soon() {
    window.clearTimeout(timer);
    timer = window.setTimeout(fit, 50);
  }

  function watch() {
    fit();
    window.setTimeout(fit, 300);
    window.setTimeout(fit, 1200);
    try {
      var win = frame.contentWindow;
      var doc = frame.contentDocument;
      if (!win || !doc || win.__mtdHeightWatch) return;
      win.__mtdHeightWatch = true;
      win.addEventListener("mtd-quiz:event", soon);
      var observer = new MutationObserver(soon);
      observer.observe(doc.documentElement, {
        subtree: true,
        childList: true,
        attributes: true,
        characterData: true,
      });
      if (window.ResizeObserver) {
        new ResizeObserver(soon).observe(doc.body || doc.documentElement);
      }
    } catch (error) {
      /* file:// opaque origin */
    }
  }

  frame.addEventListener("load", watch);
  window.setInterval(fit, 250);
  window.addEventListener("resize", soon);
})();

/* Variant A / B only — advance the embedded quiz past its entry card, and
 * (Variant A only) dress the modal iframe to Figma 3776:6405.
 *
 * Both Figma frames draw the quiz at "Step 1 of 7" (3776:6405 and 3795:3228,
 * referencing 3377:75836 step 1), because the page has already asked the visitor
 * to take the check: Variant A's secondary CTA says "Take the MTD check" and
 * Variant B's intro CTA says "Start the MTD check". The compiled quiz still opens
 * on its own entry card, and it has no deep-link support, so the variant pages
 * click through it once on load to land on the state the design shows.
 *
 * Variant A only (the page carries .mtd-quiz-modal--figma-a):
 *   - inject variant-quiz-figma.css into the modal iframe (fonts, the Figma
 *     layout with fluid widths down to laptop viewports, progress bar, answer
 *     cards — everything the frozen bundle cannot express from the outside);
 *   - fit the iframe height to the quiz's rendered content (the React tree
 *     mounts asynchronously, so a static height is always wrong), re-fitting
 *     on resize and after webfonts load so the dialog hugs its content;
 *   - rewrite the progress fill as a % of the track (the bundle bakes a
 *     pixel width per step from the pre-restyle track);
 *   - swap the two Q1 card icons for the approved 60px light set;
 *   - hide the helper line and the support CTA, which Figma 3776:6405 does not
 *     draw.
 *
 * The registered mtd-income-tax page does not load this file.
 */
(function () {
  var FRAMES = ["mtd-quiz-frame", "mtd-quiz-modal-frame"];
  var ENTRY = /start your mtd check/i;
  var TRIES = 40; // 250ms apart (~10s) — the vendor bundle mounts asynchronously

  function advance(frame) {
    if (frame.dataset.mtdAdvanced === "1") return true;
    var doc;
    try {
      doc = frame.contentDocument;
    } catch (error) {
      return false; // opaque origin; nothing to drive
    }
    if (!doc || !doc.body) return false;
    var candidates = doc.querySelectorAll("button, a, [role='button']");
    for (var i = 0; i < candidates.length; i++) {
      var el = candidates[i];
      if (ENTRY.test((el.textContent || "").replace(/\s+/g, " ").trim())) {
        frame.dataset.mtdAdvanced = "1";
        el.click();
        return true;
      }
    }
    return false;
  }

  /* ── Variant A modal dressing (Figma 3776:6405) ─────────────────────── */

  function isFigmaAModal(frame) {
    return (
      frame.id === "mtd-quiz-modal-frame" &&
      document.querySelector(".mtd-quiz-modal--figma-a")
    );
  }

  function ensureFigmaCss(frame) {
    if (frame.dataset.mtdFigmaCss === "1") return;
    var doc;
    try {
      doc = frame.contentDocument;
    } catch (error) {
      return;
    }
    if (!doc || !doc.head) return;
    var link = doc.createElement("link");
    link.rel = "stylesheet";
    link.href = "../variant-quiz-figma.css";
    doc.head.appendChild(link);
    frame.dataset.mtdFigmaCss = "1";
  }

  /* Copy of quiz-frame.js's fitter, pointed at the modal iframe. The quiz's
     main is height:auto once the injected CSS has cleared min-height, so
     body.scrollHeight is the real content box.
     Measure the BODY only, never documentElement: the document element's
     scrollHeight is at least the iframe's current client height, so including
     it makes the height ratchet — an early tall measurement (before the
     injected Figma CSS collapses the layout) locked the frame at ~720px and
     left empty black space under the panel that the dialog then hugged. */
  function fitModalFrame(frame) {
    var doc;
    try {
      doc = frame.contentDocument;
    } catch (error) {
      return;
    }
    if (!doc || !doc.body || !doc.documentElement) return;
    var bodyHeight = doc.body.scrollHeight;
    var layoutHeight = Math.ceil(doc.body.getBoundingClientRect().height);
    var height = Math.max(bodyHeight, layoutHeight, 480);
    if (height > 0) frame.style.height = height + "px";
  }

  /* The green fill's width is baked into a styled-components class at render
     time from the pre-restyle 1272px track. After the injected CSS narrows the
     track to 783px, rewrite the fill as a % of the track so step 1 is
     783/7 ≈ 112px and later steps stay proportional. */
  function fixProgressFill(frame) {
    var doc;
    try {
      doc = frame.contentDocument;
    } catch (error) {
      return;
    }
    if (!doc || !doc.body) return;
    var m = /Step\s+(\d+)\s+of\s+(\d+)/i.exec(doc.body.innerText || "");
    if (!m) return;
    var pct = Number(m[1]) / Number(m[2]);
    var track = doc.querySelector('[class~="jroPAt"]');
    var green = track && track.firstElementChild;
    if (green) green.style.width = (pct * 100).toFixed(4) + "%";
  }

  /* Q1 uses the approved detailed-icon set (mail-opened, question-circle at
     60px, light = white). The frozen bundle ships different kit icons; swap
     them once the Q1 screen is on. Other questions keep the bundle's own
     icons. Paths are relative to THIS page (variant-a/index.html sits beside
     mtd-income-tax/), not to the quiz iframe document. */
  var ICONS = {
    mail: "../mtd-income-tax/assets/m-n-o-mail-opened--60--light.svg",
    question: "../mtd-income-tax/assets/p-q-r-question-circle--60--light.svg"
  };
  var iconCache = {};

  function fetchIcon(name) {
    if (iconCache[name]) return iconCache[name];
    iconCache[name] = fetch(ICONS[name])
      .then(function (r) {
        return r.text();
      })
      .catch(function () {
        return "";
      });
    return iconCache[name];
  }

  function swapQ1Icons(frame) {
    var doc;
    try {
      doc = frame.contentDocument;
    } catch (error) {
      return;
    }
    if (!doc || !doc.body) return;
    if (!/Q1\./.test(doc.body.innerText || "")) return;
    var cards = doc.querySelectorAll(
      '[class*="StyledButton-sc-d53fa8c3-4"]'
    );
    if (cards.length < 2) return;
    if (cards[0].dataset.mtdIcon === "mail") return;
    Promise.all([fetchIcon("mail"), fetchIcon("question")]).then(function (svgs) {
      if (!svgs[0] || !svgs[1]) return;
      var s1 = cards[0].querySelector('[role="img"]');
      var s2 = cards[1].querySelector('[role="img"]');
      if (s1) {
        s1.innerHTML = svgs[0];
        s1.dataset.mtdIcon = "mail";
      }
      if (s2) {
        s2.innerHTML = svgs[1];
        s2.dataset.mtdIcon = "question";
      }
      fitModalFrame(frame);
    });
  }

  /* Figma 3776:6405 has no helper line under Q1 and no support CTA. */
  function hideFigmaExtras(frame) {
    var doc;
    try {
      doc = frame.contentDocument;
    } catch (error) {
      return;
    }
    if (!doc) return;
    var desc = doc.querySelectorAll(".mtd-description");
    for (var i = 0; i < desc.length; i++) desc[i].classList.add("mtd-figma-a-hide");
    var support = doc.querySelectorAll(
      '[class*="sc-kZOrUD"], [class*="jqYjtI"]'
    );
    for (var j = 0; j < support.length; j++) {
      var el = support[j];
      if (/get in touch for support/i.test(el.textContent || "")) {
        el.classList.add("mtd-figma-a-hide");
      }
    }
  }

  function dressFigmaAModal(frame) {
    ensureFigmaCss(frame);
    hideFigmaExtras(frame);
    swapQ1Icons(frame);
    fixProgressFill(frame);
    fitModalFrame(frame);
    /* Sage Headline/Text swap in after first paint and reflow the title and
       the card copy — re-fit once the quiz document's fonts have settled. */
    if (frame.dataset.mtdFontsFit !== "1") {
      var doc;
      try {
        doc = frame.contentDocument;
      } catch (error) {
        doc = null;
      }
      if (doc && doc.fonts && doc.fonts.ready) {
        frame.dataset.mtdFontsFit = "1";
        doc.fonts.ready.then(function () {
          fitModalFrame(frame);
        });
      }
    }
  }

  /* The quiz re-wraps when the dialog's width changes with the window, so the
     fitted height has to follow. Debounced to one re-dress per resize burst. */
  var resizeTimer = null;
  window.addEventListener("resize", function () {
    if (resizeTimer) clearTimeout(resizeTimer);
    resizeTimer = setTimeout(function () {
      resizeTimer = null;
      FRAMES.forEach(function (id) {
        var frame = document.getElementById(id);
        if (frame && isFigmaAModal(frame)) dressFigmaAModal(frame);
      });
    }, 150);
  });

  var tries = 0;
  var timer = setInterval(function () {
    tries += 1;
    var pending = false;
    FRAMES.forEach(function (id) {
      var frame = document.getElementById(id);
      if (!frame) return;
      if (!advance(frame)) pending = true;
      if (isFigmaAModal(frame)) dressFigmaAModal(frame);
    });
    /* Keep the interval alive while the modal is still dressing (the React
       tree re-renders after the entry click, so Q1 appears a beat later);
       stop once both frames have advanced and the fitter has had a few more
       ticks to settle, or after TRIES. */
    var modal = document.getElementById("mtd-quiz-modal-frame");
    var dressing = isFigmaAModal(modal) && modal && modal.dataset.mtdAdvanced === "1" && tries < TRIES + 20;
    if ((!pending && !dressing) || tries >= TRIES + 20) clearInterval(timer);
  }, 250);

  /* The quiz re-renders on every answer click; keep the fitter and the progress
     fill in sync after that. */
  document.addEventListener("mtd-quiz:event", function () {
    FRAMES.forEach(function (id) {
      var frame = document.getElementById(id);
      if (frame && isFigmaAModal(frame)) dressFigmaAModal(frame);
    });
  });
})();

