const { chromium } = require('playwright');
const BASE = 'http://127.0.0.1:8908';
(async () => {
  const b = await chromium.launch();
  for (const width of [880, 358]) {
    const p = await b.newPage({ viewport: { width, height: 640 } });
    await p.goto(BASE + '/ongoing_project/MTD/page/quiz/index.html', { waitUntil: 'load' });
    await p.evaluate(() => { document.documentElement.classList.add('sage-open'); const l = document.getElementById('sage-page-gate-lock'); if (l) l.remove(); const w = document.getElementById('sage-page-gate'); if (w) { w.hidden = true; w.style.display = 'none'; } });
    await p.waitForTimeout(700);
    const heights = [];
    const snap = async (label) => {
      const f = await p.evaluate(() => ({ h: document.documentElement.scrollHeight, t: (document.body.innerText || '').replace(/\s+/g, ' ').slice(0, 50) }));
      heights.push(label + ':' + f.h + ' "' + f.t + '"');
    };
    await snap('landing');
    const clickByText = async (re) => {
      const ok = await p.evaluate((src) => {
        const r = new RegExp(src, 'i');
        const b = [...document.querySelectorAll('button,a')].find((n) => r.test(n.textContent) && n.offsetParent !== null);
        if (b) { b.click(); return b.textContent.trim().slice(0, 30); }
        return null;
      }, re.source);
      return ok;
    };
    await clickByText(/Start your MTD check/);
    await p.waitForTimeout(600);
    for (let i = 0; i < 8; i++) {
      const clicked = await p.evaluate(() => {
        const skip = /Previous|Get in touch|Start your|Sign|Forgot|View|Restart|Back/i;
        const b = [...document.querySelectorAll('button')].find((n) => n.offsetParent !== null && n.textContent.trim() && !skip.test(n.textContent));
        if (!b) return null;
        const label = b.textContent.trim().slice(0, 30);
        b.click();
        return label;
      });
      await p.waitForTimeout(700);
      await snap('step' + (i + 1));
      if (!clicked) break;
    }
    console.log(width, heights.join(' | '));
    await p.close();
  }
  await b.close();
})();

